/**
 * BEAN FX — Editing commands (Milestone 1, shared editing core).
 *
 * Every timeline mutation — user or AI-originated — is one of these commands,
 * validated by zod and applied by pure functions that return the new sequence
 * AND an explicit inverse (a list of commands) for undo. AI proposals never
 * touch media or execute anything: they are commands, and they are rejected
 * when they would produce an invalid timeline (directive §3/§8/§14).
 *
 * Application is deterministic: ids involved in structural changes are part
 * of the command payload (generated by callers, referenced by proposals), so
 * the same command always yields the same result.
 */
import { z } from "zod";
import {
  assertValidSequence,
  clipEndFrame,
  clipTimelineDuration,
  validateSequence,
  CaptionStyleSchema,
  EffectSchema,
  KeyframeSchema,
  TransformSchema,
  TrackSchema,
  TransitionKind,
  type Clip,
  type Sequence,
  type Track,
  AudioBusSchema,
} from "./model";
import { assertValidRange, makeRational, type Rational } from "./time";
import { filterSpec } from "@/lib/editor/filters";
import type { Effect } from "./model";
import { NikkiGraphicStyleSchema } from "@/lib/nikki/types";

export class EditorError extends Error {
  constructor(
    public code:
      | "INVALID_COMMAND"
      | "CLIP_NOT_FOUND"
      | "TRACK_NOT_FOUND"
      | "INVALID_RANGES"
      | "TRANSITION_CONFLICT"
      | "TRACK_NOT_EMPTY"
      | "INVALID_TIMELINE",
    message: string,
  ) {
    super(message);
    this.name = "EditorError";
  }
}

const idSchema = z.string().min(1).max(64);

const ClipCore = z.object({
  id: idSchema,
  trackId: idSchema,
  sourceAssetId: z.string().max(64).default(""),
  sourceInFrame: z.number().int().min(0),
  sourceOutFrame: z.number().int().min(0),
  // M48-H1 — optional independent audio stream range (see model.ts). Omitted
  // = the audio follows the video range; a clip may also arrive already
  // unlinked with a distinct audio range.
  audioSourceInFrame: z.number().int().min(0).nullable().default(null),
  audioSourceOutFrame: z.number().int().min(0).nullable().default(null),
  avLinked: z.boolean().default(true),
  sourceFps: z.object({ num: z.number().int().positive(), den: z.number().int().positive() }),
  timelineStartFrame: z.number().int().min(0),
  playbackSpeed: z.number().positive().max(16).default(1),
  volume: z.number().min(0).max(4).default(1),
  muted: z.boolean().default(false),
  fadeInFrames: z.number().int().min(0).default(0),
  fadeOutFrames: z.number().int().min(0).default(0),
  transform: TransformSchema.prefault({}),
  captionText: z.string().max(2000).nullable().default(null),
  captionStyle: CaptionStyleSchema.nullable().default(null),
  graphicTemplateId: z.string().max(64).nullable().default(null),
  graphicStyle: NikkiGraphicStyleSchema.nullable().default(null),
  label: z.string().max(120).nullable().default(null),
  missingMedia: z.boolean().default(false),
  pan: z.number().min(-1).max(1).default(0),
  groupId: z.string().max(64).nullable().default(null),
  effects: z.array(EffectSchema).max(32).default([]),
  keyframes: z.array(KeyframeSchema).max(512).default([]),
});

export const CommandSchema = z.discriminatedUnion("type", [
  z.object({ type: z.literal("AddTrack"), track: TrackSchema }),
  z.object({ type: z.literal("RemoveTrack"), trackId: idSchema }),
  z.object({
    type: z.literal("UpdateTrack"),
    trackId: idSchema,
    visible: z.boolean().optional(),
    muted: z.boolean().optional(),
    solo: z.boolean().optional(),
    locked: z.boolean().optional(),
    name: z.string().min(1).max(80).optional(),
    volume: z.number().min(0).max(4).optional(),
  }),
  z.object({ type: z.literal("AddClip"), clip: ClipCore }),
  z.object({ type: z.literal("RemoveClip"), clipId: idSchema }),
  z.object({
    type: z.literal("SplitClip"),
    clipId: idSchema,
    atTimelineFrame: z.number().int(),
    newLeftId: idSchema,
    newRightId: idSchema,
  }),
  z.object({
    type: z.literal("TrimClip"),
    clipId: idSchema,
    newSourceInFrame: z.number().int().min(0).optional(),
    newSourceOutFrame: z.number().int().min(0).optional(),
    newTimelineStartFrame: z.number().int().min(0).optional(),
  }),
  z.object({
    // M48-H1 — trim the AUDIO stream only (J/L cuts, manual A/V sync). The
    // video range and the clip's timeline window are untouched; the command
    // auto-unlinks (avLinked=false) because a distinct audio range IS the
    // unlinked state. Reversible: the inverse restores the previous audio
    // range and the previous link flag.
    type: z.literal("TrimClipAudioStream"),
    clipId: idSchema,
    newAudioSourceInFrame: z.number().int().min(0).nullable().optional(),
    newAudioSourceOutFrame: z.number().int().min(0).nullable().optional(),
  }),
  z.object({
    // M48-H1 — linked/unlinked A/V control. Linking resolves to the VIDEO
    // range (the timeline window is video-authoritative): the audio range is
    // reset to null and the audio follows the video again.
    type: z.literal("SetClipAvLink"),
    clipId: idSchema,
    linked: z.boolean(),
  }),
  z.object({
    // M48-H2 — bus configuration. All four commands are reversible and the
    // ONLY way bus state changes (no direct writes from AI or UI).
    type: z.literal("AddBus"),
    bus: AudioBusSchema,
  }),
  z.object({
    type: z.literal("RemoveBus"),
    busId: idSchema,
  }),
  z.object({
    type: z.literal("UpdateBus"),
    busId: idSchema,
    name: z.string().min(1).max(40).optional(),
    gain: z.number().min(0).max(4).optional(),
    pan: z.number().min(-1).max(1).optional(),
    muted: z.boolean().optional(),
    solo: z.boolean().optional(),
  }),
  z.object({
    type: z.literal("AssignTrackBus"),
    trackId: idSchema,
    /** Null = unassign (route straight to the master). */
    busId: idSchema.nullable(),
  }),
  z.object({
    type: z.literal("MoveClip"),
    clipId: idSchema,
    newTimelineStartFrame: z.number().int().min(0),
    newTrackId: idSchema.optional(),
  }),
  z.object({ type: z.literal("RippleDelete"), clipId: idSchema }),
  z.object({ type: z.literal("InsertClip"), clip: ClipCore }),
  z.object({
    type: z.literal("ReplaceClip"),
    clipId: idSchema,
    newSourceAssetId: z.string().max(64),
    newSourceInFrame: z.number().int().min(0),
    newSourceOutFrame: z.number().int().min(0),
    newSourceFps: z.object({ num: z.number().int().positive(), den: z.number().int().positive() }).optional(),
  }),
  z.object({
    /** M29 P5 — bulk relink: re-point every clip referencing a dead asset id.
     *  One atomic, reversible history entry; never alters in/out or placement. */
    type: z.literal("RelinkAssets"),
    mappings: z.array(z.object({
      deadAssetId: z.string().max(64),
      newAssetId: z.string().max(64),
    })).min(1).max(200),
  }),
  z.object({
    type: z.literal("AddTransition"),
    transitionId: idSchema,
    trackId: idSchema,
    kind: TransitionKind,
    startFrame: z.number().int().min(0),
    durationFrames: z.number().int().min(1),
    params: z.record(z.string(), z.number()).default({}),
  }),
  z.object({ type: z.literal("RemoveTransition"), transitionId: idSchema }),
  z.object({
    type: z.literal("AddEffect"),
    clipId: idSchema,
    effect: EffectSchema,
  }),
  z.object({ type: z.literal("RemoveEffect"), clipId: idSchema, effectId: idSchema }),
  z.object({ type: z.literal("AddCaption"), clip: ClipCore }),
  z.object({ type: z.literal("AddGraphic"), clip: ClipCore }),
  z.object({
    type: z.literal("SetKeyframe"),
    clipId: idSchema,
    keyframe: KeyframeSchema,
  }),
  z.object({ type: z.literal("RemoveKeyframe"), clipId: idSchema, keyframeId: idSchema }),
  z.object({ type: z.literal("ChangeVolume"), clipId: idSchema, volume: z.number().min(0).max(4) }),
  z.object({ type: z.literal("ChangePlaybackSpeed"), clipId: idSchema, speed: z.number().positive().max(16) }),
  z.object({
    type: z.literal("UpdateClipProperties"),
    clipId: idSchema,
    transform: ClipCore.shape.transform.optional(),
    muted: z.boolean().optional(),
    label: z.string().max(120).nullable().optional(),
    pan: z.number().min(-1).max(1).optional(),
    // M48-H1 — independent audio stream range + link flag (also the inverse
    // payload of TrimClipAudioStream / SetClipAvLink).
    audioSourceInFrame: z.number().int().min(0).nullable().optional(),
    audioSourceOutFrame: z.number().int().min(0).nullable().optional(),
    avLinked: z.boolean().optional(),
    fadeInFrames: z.number().int().min(0).optional(),
    fadeOutFrames: z.number().int().min(0).optional(),
    captionText: z.string().max(2000).nullable().optional(),
    captionStyle: CaptionStyleSchema.nullable().optional(),
    graphicTemplateId: z.string().max(64).nullable().optional(),
    graphicStyle: NikkiGraphicStyleSchema.nullable().optional(),
  }),
  // M26 P1 — markers, groups, gap removal, alignment.
  z.object({ type: z.literal("AddMarker"), marker: z.object({ id: idSchema, frame: z.number().int().min(0), label: z.string().max(120).default("") }) }),
  z.object({ type: z.literal("RemoveMarker"), markerId: idSchema }),
  z.object({
    type: z.literal("UpdateMarker"),
    markerId: idSchema,
    newFrame: z.number().int().min(0).optional(),
    newLabel: z.string().max(120).optional(),
  }),
  z.object({ type: z.literal("GroupClips"), clipIds: z.array(idSchema).min(2).max(200), groupId: idSchema }),
  z.object({ type: z.literal("UngroupClips"), clipIds: z.array(idSchema).min(1).max(200) }),
  /** Close inter-clip gaps on the given tracks (default: every track).
   *  Refuses tracks that carry transitions — moving clips would invalidate
   *  their frame windows (never silently rewritten). */
  z.object({ type: z.literal("CloseGaps"), trackIds: z.array(idSchema).max(64).optional() }),
  /** Align the start of every listed clip to one frame. */
  z.object({ type: z.literal("AlignClipsToPlayhead"), clipIds: z.array(idSchema).min(1).max(200), frame: z.number().int().min(0) }),
  /** M26 P1 — low-level group tag (GroupClips/UngroupClips compile to this). */
  z.object({ type: z.literal("SetClipGroup"), clipId: idSchema, groupId: z.string().max(64).nullable() }),
  /** M27 P1 — ROLL EDIT: move the shared boundary between two ADJACENT clips.
   *  The left clip's source out-point and the right clip's source in-point
   *  shift by the same frame count (the timeline boundary moves; neither clip
   *  changes start-of-sequence position on the outside). Sequence duration is
   *  preserved: the right clip's END stays fixed and the left clip's START
   *  stays fixed. Absolute integer-frame boundary target (snapping done in UI). */
  z.object({
    type: z.literal("RollEdit"),
    leftClipId: idSchema,
    rightClipId: idSchema,
    newBoundaryFrame: z.number().int().min(0),
  }),
  // M27 P2 — per-effect parameter keyframes (visual effects only; the volume
  // effect keeps its dedicated M17/M18 automation system).
  z.object({
    type: z.literal("SetEffectKeyframe"),
    clipId: idSchema,
    effectId: idSchema,
    keyframe: z.object({
      id: idSchema,
      param: z.string().min(1).max(32),
      frame: z.number().int().min(0),
      value: z.number(),
      interpolation: z.enum(["HOLD", "LINEAR", "EASE_IN", "EASE_OUT", "EASE_IN_OUT"]).default("LINEAR"),
    }),
  }),
  z.object({ type: z.literal("RemoveEffectKeyframe"), clipId: idSchema, effectId: idSchema, keyframeId: idSchema }),
  /** Bulk replace of one effect's animation state — the exact inverse unit. */
  z.object({
    type: z.literal("SetEffectKeyframes"),
    clipId: idSchema,
    effectId: idSchema,
    keyframes: z.array(z.object({
      id: idSchema,
      param: z.string().min(1).max(32),
      frame: z.number().int().min(0),
      value: z.number(),
      interpolation: z.enum(["HOLD", "LINEAR", "EASE_IN", "EASE_OUT", "EASE_IN_OUT"]).default("LINEAR"),
    })).max(256),
    animatedParams: z.array(z.string().max(32)).max(16),
  }),
  z.object({
    type: z.literal("ToggleEffectParamAnimation"),
    clipId: idSchema,
    effectId: idSchema,
    param: z.string().min(1).max(32),
    enabled: z.boolean(),
  }),
]);
export type Command = z.infer<typeof CommandSchema>;

export function parseCommand(input: unknown): Command {
  const result = CommandSchema.safeParse(input);
  if (!result.success) {
    // M45 — include the failing field path: callers (API consumers, MCP tools,
    // the AI executor) must be able to see WHICH field was rejected, not just
    // that "an object was expected" somewhere.
    const issue = result.error.issues[0];
    const where = issue?.path?.length ? issue.path.join(".") : "(command root)";
    throw new EditorError("INVALID_COMMAND", `command rejected by schema validation at ${where}: ${issue?.message ?? "unknown"}`);
  }
  return result.data;
}

export interface ApplyResult {
  sequence: Sequence;
  /** Commands that undo this command — the list is applied in REVERSE order
   *  to undo, so composite inverses are ordered [restore-latest … first]. */
  inverse: Command[];
}

function clone<T>(value: T): T {
  return structuredClone(value);
}

function rational(r: { num: number; den: number }): Rational {
  return makeRational(r.num, r.den);
}

/** Timeline frames → source frames for a clip's timebases and speed. */
function srcFromTimeline(timelineFrames: number, clip: { sourceFps: { num: number; den: number } }, seq: Sequence, speed: number): number {
  return Math.round((timelineFrames * speed * clip.sourceFps.num * seq.fps.den) / (clip.sourceFps.den * seq.fps.num));
}

function findClip(seq: Sequence, clipId: string): Clip {
  const clip = seq.clips.find((c) => c.id === clipId);
  if (!clip) throw new EditorError("CLIP_NOT_FOUND", `clip ${clipId} does not exist`);
  return clip;
}

function findTrack(seq: Sequence, trackId: string): Track {
  const track = seq.tracks.find((t) => t.id === trackId);
  if (!track) throw new EditorError("TRACK_NOT_FOUND", `track ${trackId} does not exist`);
  return track;
}

function buildClip(core: z.infer<typeof ClipCore>, seq: Sequence): Clip {
  let duration: number;
  try {
    duration = clipTimelineDuration(core.sourceOutFrame, core.sourceInFrame, rational(core.sourceFps), rational(seq.fps), core.playbackSpeed);
  } catch (e) {
    throw new EditorError("INVALID_RANGES", e instanceof Error ? e.message : String(e));
  }
  if (core.trackId && findTrack(seq, core.trackId).kind === "CAPTION" && !core.captionText) {
    throw new EditorError("INVALID_COMMAND", `caption clip ${core.id} requires captionText`);
  }
  return {
    ...core,
    timelineDurationFrames: duration,
    keyframes: [...core.keyframes].sort((a, b) => a.frame - b.frame),
  };
}

/** Shift every clip on `trackId` that starts at or after `fromFrame` by `delta`. */
function shiftFrom(seq: Sequence, trackId: string, fromFrame: number, delta: number): Command[] {
  const inverses: Command[] = [];
  for (const c of seq.clips) {
    if (c.trackId === trackId && c.timelineStartFrame >= fromFrame) {
      inverses.unshift({ type: "MoveClip", clipId: c.id, newTimelineStartFrame: c.timelineStartFrame });
      c.timelineStartFrame = Math.max(0, c.timelineStartFrame + delta);
    }
  }
  return inverses;
}

function addClipImpl(seq: Sequence, clip: Clip, inverse: Command[]): void {
  const track = findTrack(seq, clip.trackId);
  if (track.locked) throw new EditorError("INVALID_TIMELINE", `track ${track.id} is locked — edit refused`);
  if (clipEndFrame(seq, clip) < clip.timelineStartFrame + 1) throw new EditorError("INVALID_RANGES", "clip duration below one frame");
  seq.clips.push(clip);
  inverse.unshift({ type: "RemoveClip", clipId: clip.id });
}

// -------------------------------------------------------------------------------- per-command application

function applyAddTrack(seq: Sequence, cmd: Extract<Command, { type: "AddTrack" }>, inverse: Command[]): void {
  if (seq.tracks.some((t) => t.id === cmd.track.id)) {
    throw new EditorError("INVALID_COMMAND", `track ${cmd.track.id} already exists`);
  }
  seq.tracks.push(cmd.track);
  inverse.unshift({ type: "RemoveTrack", trackId: cmd.track.id });
}

function applyRemoveTrack(seq: Sequence, cmd: Extract<Command, { type: "RemoveTrack" }>, inverse: Command[]): void {
  const track = findTrack(seq, cmd.trackId);
  const hasClips = seq.clips.some((c) => c.trackId === cmd.trackId);
  if (hasClips) throw new EditorError("TRACK_NOT_EMPTY", `track ${cmd.trackId} still has clips — remove them first`);
  seq.transitions = seq.transitions.filter((t) => t.trackId !== cmd.trackId);
  seq.tracks = seq.tracks.filter((t) => t.id !== cmd.trackId);
  inverse.unshift({ type: "AddTrack", track });
}

function applyAddClip(seq: Sequence, cmd: Extract<Command, { type: "AddClip" }>, inverse: Command[]): void {
  addClipImpl(seq, buildClip(cmd.clip, seq), inverse);
}

function applyRemoveClip(seq: Sequence, cmd: Extract<Command, { type: "RemoveClip" }>, inverse: Command[]): void {
  const clip = findClip(seq, cmd.clipId);
  const track = findTrack(seq, clip.trackId);
  if (track.locked) throw new EditorError("INVALID_TIMELINE", `track ${track.id} is locked — edit refused`);
  seq.transitions = seq.transitions.filter((t) => t.clipAId !== clip.id && t.clipBId !== clip.id);
  seq.clips = seq.clips.filter((c) => c.id !== clip.id);
  inverse.unshift({ type: "AddClip", clip: clone(clip) });
}

function applySplitClip(seq: Sequence, cmd: Extract<Command, { type: "SplitClip" }>, inverse: Command[]): void {
  const original = clone(findClip(seq, cmd.clipId));
  const track = findTrack(seq, original.trackId);
  if (track.locked) throw new EditorError("INVALID_TIMELINE", `track ${track.id} is locked — edit refused`);
  const start = original.timelineStartFrame;
  const end = clipEndFrame(seq, original);
  if (cmd.atTimelineFrame <= start || cmd.atTimelineFrame >= end) {
    throw new EditorError("INVALID_RANGES", `split point ${cmd.atTimelineFrame} must be strictly inside clip ${cmd.clipId} [${start}, ${end})`);
  }
  const seq2 = clone(seq);
  const left = findClip(seq2, cmd.clipId);
  const leftDur = cmd.atTimelineFrame - start;
  const rightDur = end - cmd.atTimelineFrame;
  // Source split point: inverse-map the timeline cut, then snap ±2 so BOTH
  // sides recompute exactly to their timeline durations (integer timebases).
  let srcMid = original.sourceInFrame + srcFromTimeline(leftDur, original, seq, original.playbackSpeed);
  let ok = false;
  for (const offset of [0, 1, -1, 2, -2]) {
    const candidate = srcMid + offset;
    if (candidate <= original.sourceInFrame || candidate >= original.sourceOutFrame) continue;
    const leftDurR = clipTimelineDuration(candidate, original.sourceInFrame, rational(original.sourceFps), rational(seq.fps), original.playbackSpeed);
    const rightDurR = clipTimelineDuration(original.sourceOutFrame, candidate, rational(original.sourceFps), rational(seq.fps), original.playbackSpeed);
    if (leftDurR === leftDur && rightDurR === rightDur) {
      srcMid = candidate;
      ok = true;
      break;
    }
  }
  if (!ok) {
    // Honest failure: extreme timebase/speed combos where one source frame
    // spans more than the tolerance cannot split exactly at that frame.
    throw new EditorError(
      "INVALID_RANGES",
      `cannot split clip ${cmd.clipId} exactly at frame ${cmd.atTimelineFrame} with these timebases — snap the split to a source frame boundary`,
    );
  }
  left.sourceOutFrame = srcMid;
  left.timelineDurationFrames = leftDur;
  const right: Clip = {
    ...clone(original),
    id: cmd.newRightId,
    sourceInFrame: srcMid,
    timelineStartFrame: cmd.atTimelineFrame,
    timelineDurationFrames: rightDur,
    fadeInFrames: 0,
    fadeOutFrames: original.fadeOutFrames,
    keyframes: clone(original.keyframes),
  };
  left.fadeOutFrames = 0;
  left.keyframes = left.keyframes.filter((k) => k.frame < leftDur);
  right.keyframes = right.keyframes
    .map((k) => ({ ...k, frame: k.frame - leftDur }))
    .filter((k) => k.frame >= 0);
  if (cmd.newLeftId !== cmd.clipId) left.id = cmd.newLeftId;
  seq2.clips.push(right);
  // Undo (applied in reverse list order): remove the right half, remove the
  // renamed left half, then re-add the original unsplit clip.
  inverse.unshift(
    { type: "AddClip", clip: clone(original) },
    { type: "RemoveClip", clipId: cmd.newLeftId },
    { type: "RemoveClip", clipId: cmd.newRightId },
  );
  Object.assign(seq, seq2);
}

function applyTrimClip(seq: Sequence, cmd: Extract<Command, { type: "TrimClip" }>, inverse: Command[]): void {
  const clip = findClip(seq, cmd.clipId);
  const track = findTrack(seq, clip.trackId);
  if (track.locked) throw new EditorError("INVALID_TIMELINE", `track ${track.id} is locked — edit refused`);
  const before = clone(clip);
  if (cmd.newSourceInFrame !== undefined) {
    if (cmd.newSourceInFrame >= clip.sourceOutFrame) {
      throw new EditorError("INVALID_RANGES", `new source in ${cmd.newSourceInFrame} must stay below source out ${clip.sourceOutFrame}`);
    }
    const headCut = clipTimelineDuration(cmd.newSourceInFrame, clip.sourceInFrame, rational(clip.sourceFps), rational(seq.fps), clip.playbackSpeed);
    clip.sourceInFrame = cmd.newSourceInFrame;
    clip.timelineStartFrame = cmd.newTimelineStartFrame ?? clip.timelineStartFrame + headCut;
  }
  if (cmd.newSourceOutFrame !== undefined) {
    if (cmd.newSourceOutFrame <= clip.sourceInFrame) {
      throw new EditorError("INVALID_RANGES", `new source out ${cmd.newSourceOutFrame} must stay above source in ${clip.sourceInFrame}`);
    }
    clip.sourceOutFrame = cmd.newSourceOutFrame;
  }
  if (cmd.newTimelineStartFrame !== undefined && cmd.newSourceInFrame === undefined) {
    clip.timelineStartFrame = cmd.newTimelineStartFrame;
  }
  clip.timelineDurationFrames = clipTimelineDuration(clip.sourceOutFrame, clip.sourceInFrame, rational(clip.sourceFps), rational(seq.fps), clip.playbackSpeed);
  inverse.unshift({ type: "UpdateClipProperties", clipId: clip.id, transform: before.transform, muted: before.muted, label: before.label, fadeInFrames: before.fadeInFrames, fadeOutFrames: before.fadeOutFrames }, {
    type: "ReplaceClip",
    clipId: clip.id,
    newSourceAssetId: before.sourceAssetId,
    newSourceInFrame: before.sourceInFrame,
    newSourceOutFrame: before.sourceOutFrame,
    newSourceFps: before.sourceFps,
  }, { type: "MoveClip", clipId: clip.id, newTimelineStartFrame: before.timelineStartFrame });
}

function applyTrimClipAudioStream(seq: Sequence, cmd: Extract<Command, { type: "TrimClipAudioStream" }>, inverse: Command[]): void {
  const clip = findClip(seq, cmd.clipId);
  const track = findTrack(seq, clip.trackId);
  if (track.locked) throw new EditorError("INVALID_TIMELINE", `track ${track.id} is locked — edit refused`);
  const before = { audioSourceInFrame: clip.audioSourceInFrame, audioSourceOutFrame: clip.audioSourceOutFrame, avLinked: clip.avLinked };
  const inFrame = cmd.newAudioSourceInFrame ?? (clip.audioSourceInFrame ?? clip.sourceInFrame);
  const outFrame = cmd.newAudioSourceOutFrame ?? (clip.audioSourceOutFrame ?? clip.sourceOutFrame);
  if (inFrame >= outFrame) {
    throw new EditorError("INVALID_RANGES", `audio stream range ${inFrame}..${outFrame} is empty or inverted`);
  }
  clip.audioSourceInFrame = inFrame;
  clip.audioSourceOutFrame = outFrame;
  // A distinct audio range IS the unlinked state — the command unlinks by
  // construction; the inverse restores the previous range AND link flag.
  clip.avLinked = false;
  inverse.unshift({ type: "UpdateClipProperties", clipId: clip.id, audioSourceInFrame: before.audioSourceInFrame, audioSourceOutFrame: before.audioSourceOutFrame, avLinked: before.avLinked });
}

function applySetClipAvLink(seq: Sequence, cmd: Extract<Command, { type: "SetClipAvLink" }>, inverse: Command[]): void {
  const clip = findClip(seq, cmd.clipId);
  const track = findTrack(seq, clip.trackId);
  if (track.locked) throw new EditorError("INVALID_TIMELINE", `track ${track.id} is locked — edit refused`);
  const before = { audioSourceInFrame: clip.audioSourceInFrame, audioSourceOutFrame: clip.audioSourceOutFrame, avLinked: clip.avLinked };
  if (cmd.linked === clip.avLinked) return; // idempotent
  if (cmd.linked) {
    // Linking resolves to the VIDEO range: the timeline window is
    // video-authoritative, so the audio stream re-follows the video range.
    clip.audioSourceInFrame = null;
    clip.audioSourceOutFrame = null;
    clip.avLinked = true;
  } else {
    // Unlinking pins the audio range to the current effective range — the
    // streams may now diverge without moving either.
    clip.audioSourceInFrame = clip.audioSourceInFrame ?? clip.sourceInFrame;
    clip.audioSourceOutFrame = clip.audioSourceOutFrame ?? clip.sourceOutFrame;
    clip.avLinked = false;
  }
  inverse.unshift({ type: "UpdateClipProperties", clipId: clip.id, audioSourceInFrame: before.audioSourceInFrame, audioSourceOutFrame: before.audioSourceOutFrame, avLinked: before.avLinked });
}

function applyAddBus(seq: Sequence, cmd: Extract<Command, { type: "AddBus" }>, inverse: Command[]): void {
  if (seq.buses.some((b) => b.id === cmd.bus.id)) {
    throw new EditorError("INVALID_COMMAND", `bus ${cmd.bus.id} already exists`);
  }
  seq.buses.push(clone(cmd.bus));
  inverse.unshift({ type: "RemoveBus", busId: cmd.bus.id });
}

function applyRemoveBus(seq: Sequence, cmd: Extract<Command, { type: "RemoveBus" }>, inverse: Command[]): void {
  const idx = seq.buses.findIndex((b) => b.id === cmd.busId);
  if (idx === -1) throw new EditorError("INVALID_COMMAND", `bus ${cmd.busId} does not exist`);
  // Safety: a bus with assigned tracks cannot be removed — routing must stay
  // explicit (an accidental unassign would change the audible mix silently).
  const assigned = seq.tracks.filter((t) => t.busId === cmd.busId);
  if (assigned.length > 0) {
    throw new EditorError("INVALID_TIMELINE", `bus ${cmd.busId} still has ${assigned.length} assigned track(s) — unassign first`);
  }
  const [bus] = seq.buses.splice(idx, 1);
  inverse.unshift({ type: "AddBus", bus: clone(bus) });
}

function applyUpdateBus(seq: Sequence, cmd: Extract<Command, { type: "UpdateBus" }>, inverse: Command[]): void {
  const bus = seq.buses.find((b) => b.id === cmd.busId);
  if (!bus) throw new EditorError("INVALID_COMMAND", `bus ${cmd.busId} does not exist`);
  const restore: Extract<Command, { type: "UpdateBus" }> = { type: "UpdateBus", busId: bus.id };
  if (cmd.name !== undefined) { restore.name = bus.name; bus.name = cmd.name; }
  if (cmd.gain !== undefined) { restore.gain = bus.gain; bus.gain = cmd.gain; }
  if (cmd.pan !== undefined) { restore.pan = bus.pan; bus.pan = cmd.pan; }
  if (cmd.muted !== undefined) { restore.muted = bus.muted; bus.muted = cmd.muted; }
  if (cmd.solo !== undefined) { restore.solo = bus.solo; bus.solo = cmd.solo; }
  inverse.unshift(restore);
}

function applyAssignTrackBus(seq: Sequence, cmd: Extract<Command, { type: "AssignTrackBus" }>, inverse: Command[]): void {
  const track = findTrack(seq, cmd.trackId);
  if (track.locked) throw new EditorError("INVALID_TIMELINE", `track ${track.id} is locked — edit refused`);
  if (cmd.busId !== null && !seq.buses.some((b) => b.id === cmd.busId)) {
    throw new EditorError("INVALID_COMMAND", `bus ${cmd.busId} does not exist`);
  }
  const before = track.busId;
  track.busId = cmd.busId;
  inverse.unshift({ type: "AssignTrackBus", trackId: track.id, busId: before });
}

function applyMoveClip(seq: Sequence, cmd: Extract<Command, { type: "MoveClip" }>, inverse: Command[]): void {
  const clip = findClip(seq, cmd.clipId);
  const before = { start: clip.timelineStartFrame, trackId: clip.trackId };
  // A locked track refuses ALL edits of its clips — including in-place moves
  // (the engine enforces this even where the UI already blocks it).
  const from = findTrack(seq, clip.trackId);
  if (from.locked) throw new EditorError("INVALID_TIMELINE", `track ${from.id} is locked — edit refused`);
  if (cmd.newTrackId !== undefined && cmd.newTrackId !== clip.trackId) {
    const to = findTrack(seq, cmd.newTrackId);
    if (from.kind !== to.kind) {
      throw new EditorError("INVALID_TIMELINE", `cannot move clip between different track kinds (${from.kind} → ${to.kind})`);
    }
    if (to.locked) throw new EditorError("INVALID_TIMELINE", `track ${to.id} is locked — edit refused`);
    clip.trackId = cmd.newTrackId;
  }
  clip.timelineStartFrame = cmd.newTimelineStartFrame;
  inverse.unshift(
    cmd.newTrackId !== undefined
      ? { type: "MoveClip", clipId: clip.id, newTimelineStartFrame: before.start, newTrackId: before.trackId }
      : { type: "MoveClip", clipId: clip.id, newTimelineStartFrame: before.start },
  );
}

function applyRippleDelete(seq: Sequence, cmd: Extract<Command, { type: "RippleDelete" }>, inverse: Command[]): void {
  const clip = findClip(seq, cmd.clipId);
  const end = clipEndFrame(seq, clip);
  applyRemoveClip(seq, { type: "RemoveClip", clipId: cmd.clipId }, inverse);
  const shiftInverses = shiftFrom(seq, clip.trackId, end, -clip.timelineDurationFrames);
  inverse.unshift(...shiftInverses);
}

function applyInsertClip(seq: Sequence, cmd: Extract<Command, { type: "InsertClip" }>, inverse: Command[]): void {
  const track = findTrack(seq, cmd.clip.trackId);
  const clip = buildClip(cmd.clip, seq);
  const shiftInverses = shiftFrom(seq, track.id, clip.timelineStartFrame, clip.timelineDurationFrames);
  inverse.unshift(...shiftInverses);
  addClipImpl(seq, clip, inverse);
}

/** M29 P5 — bulk relink (deterministic; source in/out and timeline placement
 *  are untouched — incompatible replacements are the caller's validated choice). */
function applyRelinkAssets(seq: Sequence, cmd: Extract<Command, { type: "RelinkAssets" }>, inverse: Command[]): void {
  const map = new Map(cmd.mappings.map((m) => [m.deadAssetId, m.newAssetId]));
  const reverse: Extract<Command, { type: "RelinkAssets" }>["mappings"] = [];
  for (const clip of seq.clips) {
    const target = clip.sourceAssetId ? map.get(clip.sourceAssetId) : undefined;
    if (!target) continue;
    reverse.push({ deadAssetId: target, newAssetId: clip.sourceAssetId });
    clip.sourceAssetId = target;
    clip.missingMedia = false;
  }
  if (reverse.length > 0) inverse.push({ type: "RelinkAssets", mappings: reverse });
}

function applyReplaceClip(seq: Sequence, cmd: Extract<Command, { type: "ReplaceClip" }>, inverse: Command[]): void {
  const clip = findClip(seq, cmd.clipId);
  const before = clone(clip);
  if (cmd.newSourceOutFrame <= cmd.newSourceInFrame) {
    throw new EditorError("INVALID_RANGES", `replace source range [${cmd.newSourceInFrame}, ${cmd.newSourceOutFrame}) is empty`);
  }
  clip.sourceAssetId = cmd.newSourceAssetId;
  clip.sourceInFrame = cmd.newSourceInFrame;
  clip.sourceOutFrame = cmd.newSourceOutFrame;
  clip.sourceFps = cmd.newSourceFps ?? clip.sourceFps;
  // An empty source id means a caption/missing-media clip — a ReplaceClip
  // inverse (trim undo) restoring "" must keep missingMedia, or the restored
  // sequence fails validation and the undo throws mid-stack.
  clip.missingMedia = cmd.newSourceAssetId === "";
  clip.timelineDurationFrames = clipTimelineDuration(clip.sourceOutFrame, clip.sourceInFrame, rational(clip.sourceFps), rational(seq.fps), clip.playbackSpeed);
  inverse.unshift({
    type: "ReplaceClip",
    clipId: clip.id,
    newSourceAssetId: before.sourceAssetId,
    newSourceInFrame: before.sourceInFrame,
    newSourceOutFrame: before.sourceOutFrame,
    newSourceFps: before.sourceFps,
  });
}

function applyAddTransition(seq: Sequence, cmd: Extract<Command, { type: "AddTransition" }>, inverse: Command[]): void {
  const start = cmd.startFrame;
  const end = start + cmd.durationFrames;
  const track = findTrack(seq, cmd.trackId);
  if (track.kind !== "VIDEO" && track.kind !== "AUDIO") {
    // Transitions are a media-track concept; captions/graphics use clips.
    throw new EditorError("TRANSITION_CONFLICT", `transitions are only valid on VIDEO or AUDIO tracks (got ${track.kind})`);
  }
  const trackClips = seq.clips.filter((c) => c.trackId === cmd.trackId);
  // Professional overlap semantics: A's tail and B's head OVERLAP for the
  // transition range (a cross-dissolve composites A fading into B). A ends at
  // the transition end, B starts at the transition start.
  const a = trackClips.find((c) => clipEndFrame(seq, c) === end);
  const b = trackClips.find((c) => c.timelineStartFrame === start);
  if (!a || !b || a.id === b.id) {
    throw new EditorError(
      "TRANSITION_CONFLICT",
      `transition at [${start}, ${end}) requires overlapping clips on track ${cmd.trackId}: one ending at ${end}, another starting at ${start}`,
    );
  }
  if (seq.transitions.some((t) => t.trackId === cmd.trackId && t.startFrame < end && start < t.endFrame)) {
    throw new EditorError("TRANSITION_CONFLICT", `transition overlaps an existing transition on track ${cmd.trackId}`);
  }
  const transition = {
    id: cmd.transitionId,
    trackId: cmd.trackId,
    kind: cmd.kind,
    startFrame: start,
    endFrame: end,
    durationFrames: cmd.durationFrames,
    clipAId: a.id,
    clipBId: b.id,
    params: cmd.params,
  };
  seq.transitions.push(transition);
  inverse.unshift({ type: "RemoveTransition", transitionId: cmd.transitionId });
}

function applyRemoveTransition(seq: Sequence, cmd: Extract<Command, { type: "RemoveTransition" }>, inverse: Command[]): void {
  const tr = seq.transitions.find((t) => t.id === cmd.transitionId);
  if (!tr) throw new EditorError("TRANSITION_CONFLICT", `transition ${cmd.transitionId} does not exist`);
  seq.transitions = seq.transitions.filter((t) => t.id !== cmd.transitionId);
  inverse.unshift({
    type: "AddTransition",
    transitionId: tr.id,
    trackId: tr.trackId,
    kind: tr.kind,
    startFrame: tr.startFrame,
    durationFrames: tr.durationFrames,
    params: tr.params,
  });
}

function applyAddEffect(seq: Sequence, cmd: Extract<Command, { type: "AddEffect" }>, inverse: Command[]): void {
  const clip = findClip(seq, cmd.clipId);
  if (clip.effects.some((e) => e.id === cmd.effect.id)) {
    throw new EditorError("INVALID_COMMAND", `effect ${cmd.effect.id} already exists on clip ${cmd.clipId}`);
  }
  clip.effects.push(cmd.effect);
  inverse.unshift({ type: "RemoveEffect", clipId: clip.id, effectId: cmd.effect.id });
}

function applyRemoveEffect(seq: Sequence, cmd: Extract<Command, { type: "RemoveEffect" }>, inverse: Command[]): void {
  const clip = findClip(seq, cmd.clipId);
  const effect = clip.effects.find((e) => e.id === cmd.effectId);
  if (!effect) throw new EditorError("INVALID_COMMAND", `effect ${cmd.effectId} does not exist on clip ${cmd.clipId}`);
  clip.effects = clip.effects.filter((e) => e.id !== cmd.effectId);
  inverse.unshift({ type: "AddEffect", clipId: clip.id, effect });
}

function applyCaptionOrGraphic(
  seq: Sequence,
  clip: z.infer<typeof ClipCore>,
  inverse: Command[],
  kind: "CAPTION" | "GRAPHIC",
): void {
  const track = findTrack(seq, clip.trackId);
  if (track.kind !== kind) {
    throw new EditorError("INVALID_COMMAND", `${kind.toLowerCase()} clip ${clip.id} must live on a ${kind} track (got ${track.kind})`);
  }
  if (kind === "CAPTION" && !clip.captionText) {
    throw new EditorError("INVALID_COMMAND", `caption clip ${clip.id} requires captionText`);
  }
  if (kind === "GRAPHIC" && !clip.graphicTemplateId) {
    throw new EditorError("INVALID_COMMAND", `graphic clip ${clip.id} requires graphicTemplateId`);
  }
  addClipImpl(seq, buildClip(clip, seq), inverse);
}

function applySetKeyframe(seq: Sequence, cmd: Extract<Command, { type: "SetKeyframe" }>, inverse: Command[]): void {
  const clip = findClip(seq, cmd.clipId);
  if (cmd.keyframe.frame >= clip.timelineDurationFrames) {
    throw new EditorError("INVALID_RANGES", `keyframe frame ${cmd.keyframe.frame} is outside clip ${clip.id} (duration ${clip.timelineDurationFrames})`);
  }
  const existing = clip.keyframes.find((k) => k.property === cmd.keyframe.property && k.frame === cmd.keyframe.frame);
  if (existing) {
    inverse.unshift({ type: "SetKeyframe", clipId: clip.id, keyframe: clone(existing) });
    existing.value = cmd.keyframe.value;
    existing.interpolation = cmd.keyframe.interpolation;
  } else {
    clip.keyframes.push(clone(cmd.keyframe));
    clip.keyframes.sort((a, b) => a.frame - b.frame);
    inverse.unshift({ type: "RemoveKeyframe", clipId: clip.id, keyframeId: cmd.keyframe.id });
  }
}

function applyRemoveKeyframe(seq: Sequence, cmd: Extract<Command, { type: "RemoveKeyframe" }>, inverse: Command[]): void {
  const clip = findClip(seq, cmd.clipId);
  const kf = clip.keyframes.find((k) => k.id === cmd.keyframeId);
  if (!kf) throw new EditorError("INVALID_COMMAND", `keyframe ${cmd.keyframeId} does not exist on clip ${clip.id}`);
  clip.keyframes = clip.keyframes.filter((k) => k.id !== cmd.keyframeId);
  inverse.unshift({ type: "SetKeyframe", clipId: clip.id, keyframe: clone(kf) });
}

function applyChangeVolume(seq: Sequence, cmd: Extract<Command, { type: "ChangeVolume" }>, inverse: Command[]): void {
  const clip = findClip(seq, cmd.clipId);
  const before = clip.volume;
  clip.volume = cmd.volume;
  inverse.unshift({ type: "ChangeVolume", clipId: clip.id, volume: before });
}

function applyChangePlaybackSpeed(seq: Sequence, cmd: Extract<Command, { type: "ChangePlaybackSpeed" }>, inverse: Command[]): void {
  const clip = findClip(seq, cmd.clipId);
  const before = { speed: clip.playbackSpeed, duration: clip.timelineDurationFrames };
  clip.playbackSpeed = cmd.speed;
  // Recompute from the NEW speed — the timeline duration follows the source
  // range and the rate change.
  clip.timelineDurationFrames = clipTimelineDuration(clip.sourceOutFrame, clip.sourceInFrame, rational(clip.sourceFps), rational(seq.fps), clip.playbackSpeed);
  inverse.unshift({ type: "ChangePlaybackSpeed", clipId: clip.id, speed: before.speed });
}

function applyUpdateTrack(seq: Sequence, cmd: Extract<Command, { type: "UpdateTrack" }>, inverse: Command[]): void {
  const track = findTrack(seq, cmd.trackId);
  const restore: Extract<Command, { type: "UpdateTrack" }> = { type: "UpdateTrack", trackId: track.id };
  if (cmd.visible !== undefined) {
    restore.visible = track.visible;
    track.visible = cmd.visible;
  }
  if (cmd.muted !== undefined) {
    restore.muted = track.muted;
    track.muted = cmd.muted;
  }
  if (cmd.solo !== undefined) {
    restore.solo = track.solo;
    track.solo = cmd.solo;
  }
  if (cmd.locked !== undefined) {
    restore.locked = track.locked;
    track.locked = cmd.locked;
  }
  if (cmd.volume !== undefined) {
    restore.volume = track.volume;
    track.volume = cmd.volume;
  }
  if (cmd.name !== undefined) {
    restore.name = track.name;
    track.name = cmd.name;
  }
  inverse.unshift(restore);
}

function applyUpdateClipProperties(seq: Sequence, cmd: Extract<Command, { type: "UpdateClipProperties" }>, inverse: Command[]): void {
  const clip = findClip(seq, cmd.clipId);
  const restore: Extract<Command, { type: "UpdateClipProperties" }> = { type: "UpdateClipProperties", clipId: clip.id };
  if (cmd.transform !== undefined) {
    restore.transform = clone(clip.transform);
    clip.transform = cmd.transform;
  }
  if (cmd.muted !== undefined) {
    restore.muted = clip.muted;
    clip.muted = cmd.muted;
  }
  if (cmd.label !== undefined) {
    restore.label = clip.label;
    clip.label = cmd.label;
  }
  if (cmd.audioSourceInFrame !== undefined) {
    restore.audioSourceInFrame = clip.audioSourceInFrame;
    clip.audioSourceInFrame = cmd.audioSourceInFrame;
  }
  if (cmd.audioSourceOutFrame !== undefined) {
    restore.audioSourceOutFrame = clip.audioSourceOutFrame;
    clip.audioSourceOutFrame = cmd.audioSourceOutFrame;
  }
  if (cmd.avLinked !== undefined) {
    restore.avLinked = clip.avLinked;
    clip.avLinked = cmd.avLinked;
  }
  if (cmd.pan !== undefined) {
    restore.pan = clip.pan;
    clip.pan = cmd.pan;
  }
  if (cmd.fadeInFrames !== undefined) {
    restore.fadeInFrames = clip.fadeInFrames;
    clip.fadeInFrames = cmd.fadeInFrames;
  }
  if (cmd.fadeOutFrames !== undefined) {
    restore.fadeOutFrames = clip.fadeOutFrames;
    clip.fadeOutFrames = cmd.fadeOutFrames;
  }
  if (cmd.captionText !== undefined) {
    restore.captionText = clip.captionText;
    clip.captionText = cmd.captionText;
  }
  if (cmd.captionStyle !== undefined) {
    restore.captionStyle = clone(clip.captionStyle);
    clip.captionStyle = clone(cmd.captionStyle);
  }
  if (cmd.graphicTemplateId !== undefined) {
    restore.graphicTemplateId = clip.graphicTemplateId;
    clip.graphicTemplateId = cmd.graphicTemplateId;
  }
  if (cmd.graphicStyle !== undefined) {
    restore.graphicStyle = clone(clip.graphicStyle);
    clip.graphicStyle = clone(cmd.graphicStyle);
    // A graphic clip must keep a template id — an emptied one is an invalid
    // state, same rule as AddGraphic.
    const gTrack = seq.tracks.find((t) => t.id === clip.trackId);
    if (gTrack?.kind === "GRAPHIC" && !clip.graphicTemplateId) {
      throw new EditorError("INVALID_COMMAND", `graphic clip ${clip.id} requires graphicTemplateId`);
    }
  }
  // A caption clip must keep its text — an empty caption is an invalid state,
  // same rule as AddCaption.
  const track = seq.tracks.find((t) => t.id === clip.trackId);
  if (track?.kind === "CAPTION" && !clip.captionText) {
    throw new EditorError("INVALID_COMMAND", `caption clip ${clip.id} requires captionText`);
  }
  if (clip.fadeInFrames + clip.fadeOutFrames >= clip.timelineDurationFrames) {
    throw new EditorError("INVALID_RANGES", `fades (${clip.fadeInFrames}+${clip.fadeOutFrames}) cover the whole clip ${clip.id}`);
  }
  inverse.unshift(restore);
}

// -------------------------------------------------------------------------------- dispatcher


// ── M26 P1 — markers, groups, gap removal, alignment ────────────────────────

function applyAddMarker(seq: Sequence, cmd: Extract<Command, { type: "AddMarker" }>, inverse: Command[]): void {
  if (seq.markers.some((m) => m.id === cmd.marker.id)) {
    throw new EditorError("INVALID_COMMAND", `marker ${cmd.marker.id} already exists`);
  }
  const marker = { id: cmd.marker.id, frame: cmd.marker.frame, label: cmd.marker.label ?? "" };
  seq.markers.push(marker);
  seq.markers.sort((a, b) => a.frame - b.frame);
  inverse.unshift({ type: "RemoveMarker", markerId: marker.id });
}

function applyRemoveMarker(seq: Sequence, cmd: Extract<Command, { type: "RemoveMarker" }>, inverse: Command[]): void {
  const marker = seq.markers.find((m) => m.id === cmd.markerId);
  if (!marker) throw new EditorError("INVALID_COMMAND", `marker ${cmd.markerId} not found`);
  seq.markers = seq.markers.filter((m) => m.id !== cmd.markerId);
  inverse.unshift({ type: "AddMarker", marker: clone(marker) });
}

function applyUpdateMarker(seq: Sequence, cmd: Extract<Command, { type: "UpdateMarker" }>, inverse: Command[]): void {
  const marker = seq.markers.find((m) => m.id === cmd.markerId);
  if (!marker) throw new EditorError("INVALID_COMMAND", `marker ${cmd.markerId} not found`);
  const restore: Extract<Command, { type: "UpdateMarker" }> = { type: "UpdateMarker", markerId: marker.id };
  if (cmd.newFrame !== undefined) {
    restore.newFrame = marker.frame;
    marker.frame = cmd.newFrame;
  }
  if (cmd.newLabel !== undefined) {
    restore.newLabel = marker.label;
    marker.label = cmd.newLabel;
  }
  seq.markers.sort((a, b) => a.frame - b.frame);
  inverse.unshift(restore);
}

/** Groups share a groupId; grouping NEVER merges clips — it only tags them so
 *  multi-move/multi-delete UI acts on the set. Reversible per clip. */
function applyGroupClips(seq: Sequence, cmd: Extract<Command, { type: "GroupClips" }>, inverse: Command[]): void {
  const previous: Array<{ clipId: string; groupId: string | null }> = [];
  for (const clipId of cmd.clipIds) {
    const clip = findClip(seq, clipId);
    previous.push({ clipId: clip.id, groupId: clip.groupId ?? null });
    clip.groupId = cmd.groupId;
  }
  for (const prev of previous) {
    inverse.unshift({ type: "SetClipGroup", clipId: prev.clipId, groupId: prev.groupId });
  }
}

function applyUngroupClips(seq: Sequence, cmd: Extract<Command, { type: "UngroupClips" }>, inverse: Command[]): void {
  const previous: Array<{ clipId: string; groupId: string | null }> = [];
  for (const clipId of cmd.clipIds) {
    const clip = findClip(seq, clipId);
    previous.push({ clipId: clip.id, groupId: clip.groupId ?? null });
    clip.groupId = null;
  }
  for (const prev of previous) {
    inverse.unshift({ type: "SetClipGroup", clipId: prev.clipId, groupId: prev.groupId });
  }
}

/** M27 P1 — ROLL EDIT. Frame-accurate shared-boundary adjustment.
 *  Both clips must sit adjacent on the SAME unlocked track, share a playback
 *  speed, and have no transition attached (moving the boundary would
 *  invalidate the transition window — refused, never rewritten).
 *  The boundary must stay inside both clips and inside both source ranges.
 *  Inverse: RollEdit back to the previous boundary (exact before-state). */
function applyRollEdit(seq: Sequence, cmd: Extract<Command, { type: "RollEdit" }>, inverse: Command[]): void {
  const left = findClip(seq, cmd.leftClipId);
  const right = findClip(seq, cmd.rightClipId);
  const leftTrack = findTrack(seq, left.trackId);
  if (left.trackId !== right.trackId) throw new EditorError("INVALID_COMMAND", "roll edit requires both clips on the same track");
  if (leftTrack.locked) throw new EditorError("INVALID_TIMELINE", `track ${leftTrack.id} is locked — edit refused`);
  const leftEnd = left.timelineStartFrame + left.timelineDurationFrames;
  const rightEnd = right.timelineStartFrame + right.timelineDurationFrames;
  if (leftEnd !== right.timelineStartFrame) {
    throw new EditorError("INVALID_COMMAND", `clips are not adjacent (left ends ${leftEnd}, right starts ${right.timelineStartFrame})`);
  }
  if (left.playbackSpeed !== right.playbackSpeed) {
    throw new EditorError("INVALID_COMMAND", "roll edit requires equal playback speeds on both clips (mixed-speed roll refused)");
  }
  if (seq.transitions.some((t) => t.clipAId === left.id || t.clipBId === left.id || t.clipAId === right.id || t.clipBId === right.id)) {
    throw new EditorError("TRANSITION_CONFLICT", "roll edit refused — remove the transition on these clips first (its window would become invalid)");
  }
  const oldBoundary = leftEnd;
  const newBoundary = cmd.newBoundaryFrame;
  if (newBoundary <= left.timelineStartFrame || newBoundary >= rightEnd) {
    throw new EditorError("INVALID_RANGES", `boundary ${newBoundary} must stay inside both clips (${left.timelineStartFrame + 1}…${rightEnd - 1})`);
  }
  const delta = newBoundary - oldBoundary; // timeline frames (integer)
  // Source shift mirrors the timeline shift at the clips' common speed.
  const speed = left.playbackSpeed;
  const newLeftSourceOut = left.sourceOutFrame + delta * speed;
  const newRightSourceIn = right.sourceInFrame + delta * speed;
  if (newLeftSourceOut <= left.sourceInFrame || newRightSourceIn >= right.sourceOutFrame) {
    throw new EditorError("INVALID_RANGES", "roll exceeds the available source media on one side — clamp or trim first");
  }
  if (newRightSourceIn < 0) throw new EditorError("INVALID_RANGES", "roll would need frames before the right clip's source start");
  inverse.unshift({ type: "RollEdit", leftClipId: left.id, rightClipId: right.id, newBoundaryFrame: oldBoundary });
  // Recompute durations through the canonical integer-frame calculator so the
  // timebase stays exact (no floating-point timeline arithmetic here).
  const newLeftDur = clipTimelineDuration(newLeftSourceOut, left.sourceInFrame, rational(left.sourceFps), rational(seq.fps), speed);
  const newRightDur = clipTimelineDuration(right.sourceOutFrame, newRightSourceIn, rational(right.sourceFps), rational(seq.fps), speed);
  if (newLeftDur <= 0 || newRightDur <= 0) throw new EditorError("INVALID_RANGES", "roll produced a non-positive clip duration");
  // Boundary consistency: left keeps its start; right keeps its END.
  const effectiveBoundary = left.timelineStartFrame + newLeftDur;
  if (effectiveBoundary + newRightDur !== rightEnd) {
    // Integer rounding at exotic timebases — refuse rather than drift.
    throw new EditorError("INVALID_RANGES", "integer-frame rounding would desync the boundary at this timebase/speed — roll refused");
  }
  left.sourceOutFrame = newLeftSourceOut;
  left.timelineDurationFrames = newLeftDur;
  right.sourceInFrame = newRightSourceIn;
  right.timelineStartFrame = effectiveBoundary;
  right.timelineDurationFrames = newRightDur;
}

// ── M27 P2 — per-effect parameter keyframes ─────────────────────────────────

/** Param must belong to the effect's registry spec (never invent params) and
 *  the frame must stay inside the clip. First keyframe auto-enables the param. */
function findEffect(clip: Clip, effectId: string): Effect {
  const effect = clip.effects.find((e) => e.id === effectId);
  if (!effect) throw new EditorError("INVALID_COMMAND", `effect ${effectId} not found on clip ${clip.id}`);
  return effect;
}

function applySetEffectKeyframe(seq: Sequence, cmd: Extract<Command, { type: "SetEffectKeyframe" }>, inverse: Command[]): void {
  const clip = findClip(seq, cmd.clipId);
  const effect = findEffect(clip, cmd.effectId);
  if (effect.type === "volume") {
    throw new EditorError("INVALID_COMMAND", "the volume effect animates through the dedicated automation strip (M17/M18), not effect keyframes");
  }
  const spec = filterSpec(effect.type);
  const knownParams = new Set<string>([spec?.param.key, ...(spec?.paramExtras ?? []).map((p) => p.key)].filter((k): k is string => Boolean(k)));
  if (!knownParams.has(cmd.keyframe.param)) {
    throw new EditorError("INVALID_COMMAND", `param "${cmd.keyframe.param}" is not part of the ${effect.type} effect definition`);
  }
  if (cmd.keyframe.frame >= clip.timelineDurationFrames) {
    throw new EditorError("INVALID_RANGES", `keyframe frame ${cmd.keyframe.frame} is beyond the clip (${clip.timelineDurationFrames} frames)`);
  }
  // Exact inverse: snapshot the effect's whole animation state and restore it
  // via the bulk command (no id/slot ambiguity — moves undo perfectly).
  const prior = { keyframes: clone(effect.keyframes), animatedParams: [...effect.animatedParams] };
  const byId = effect.keyframes.find((k) => k.id === cmd.keyframe.id);
  if (byId) effect.keyframes = effect.keyframes.filter((k) => k.id !== cmd.keyframe.id);
  const slot = effect.keyframes.find((k) => k.param === cmd.keyframe.param && k.frame === cmd.keyframe.frame);
  if (slot) Object.assign(slot, clone(cmd.keyframe));
  else {
    effect.keyframes.push(clone(cmd.keyframe));
    effect.keyframes.sort((a, b) => a.frame - b.frame);
  }
  if (!effect.animatedParams.includes(cmd.keyframe.param)) {
    effect.animatedParams.push(cmd.keyframe.param);
  }
  const changed = JSON.stringify({ keyframes: effect.keyframes, animatedParams: effect.animatedParams }) !== JSON.stringify(prior);
  if (changed) inverse.unshift({ type: "SetEffectKeyframes", clipId: clip.id, effectId: effect.id, keyframes: prior.keyframes, animatedParams: prior.animatedParams });
}

function applySetEffectKeyframes(seq: Sequence, cmd: Extract<Command, { type: "SetEffectKeyframes" }>, inverse: Command[]): void {
  const clip = findClip(seq, cmd.clipId);
  const effect = findEffect(clip, cmd.effectId);
  const prior = { keyframes: clone(effect.keyframes), animatedParams: [...effect.animatedParams] };
  effect.keyframes = clone(cmd.keyframes).sort((a, b) => a.frame - b.frame);
  effect.animatedParams = [...cmd.animatedParams];
  const changed = JSON.stringify({ keyframes: effect.keyframes, animatedParams: effect.animatedParams }) !== JSON.stringify(prior);
  if (changed) inverse.unshift({ type: "SetEffectKeyframes", clipId: clip.id, effectId: effect.id, keyframes: prior.keyframes, animatedParams: prior.animatedParams });
}

function applyRemoveEffectKeyframe(seq: Sequence, cmd: Extract<Command, { type: "RemoveEffectKeyframe" }>, inverse: Command[]): void {
  const clip = findClip(seq, cmd.clipId);
  const effect = findEffect(clip, cmd.effectId);
  const kf = effect.keyframes.find((k) => k.id === cmd.keyframeId);
  if (!kf) throw new EditorError("INVALID_COMMAND", `keyframe ${cmd.keyframeId} not found on effect ${effect.id}`);
  effect.keyframes = effect.keyframes.filter((k) => k.id !== cmd.keyframeId);
  inverse.unshift({ type: "SetEffectKeyframe", clipId: clip.id, effectId: effect.id, keyframe: clone(kf) });
}

function applyToggleEffectParamAnimation(seq: Sequence, cmd: Extract<Command, { type: "ToggleEffectParamAnimation" }>, inverse: Command[]): void {
  const clip = findClip(seq, cmd.clipId);
  const effect = findEffect(clip, cmd.effectId);
  const had = effect.animatedParams.includes(cmd.param);
  if (cmd.enabled && !had) {
    effect.animatedParams.push(cmd.param);
    inverse.unshift({ type: "ToggleEffectParamAnimation", clipId: clip.id, effectId: effect.id, param: cmd.param, enabled: false });
  } else if (!cmd.enabled && had) {
    effect.animatedParams = effect.animatedParams.filter((p) => p !== cmd.param);
    inverse.unshift({ type: "ToggleEffectParamAnimation", clipId: clip.id, effectId: effect.id, param: cmd.param, enabled: true });
  }
}

function applySetClipGroup(seq: Sequence, cmd: Extract<Command, { type: "SetClipGroup" }>, inverse: Command[]): void {
  const clip = findClip(seq, cmd.clipId);
  inverse.unshift({ type: "SetClipGroup", clipId: clip.id, groupId: clip.groupId ?? null });
  clip.groupId = cmd.groupId;
}

/** CloseGaps: per targeted track, left-shift clips after the first so no two
 *  consecutive clips leave a gap. The first clip's position is preserved.
 *  Tracks with transitions are refused (moving clips would invalidate the
 *  transition windows — never silently rewritten). Inverse = MoveClip batch. */
function applyCloseGaps(seq: Sequence, cmd: Extract<Command, { type: "CloseGaps" }>, inverse: Command[]): void {
  const targetIds = cmd.trackIds && cmd.trackIds.length > 0 ? cmd.trackIds : seq.tracks.map((t) => t.id);
  for (const trackId of targetIds) {
    const track = findTrack(seq, trackId);
    if (track.locked) throw new EditorError("INVALID_TIMELINE", `track ${track.id} is locked — edit refused`);
    if (seq.transitions.some((t) => t.trackId === track.id)) {
      throw new EditorError("TRANSITION_CONFLICT", `track ${track.id} has transitions — remove them before closing gaps`);
    }
    const clips = seq.clips.filter((c) => c.trackId === track.id).sort((a, b) => a.timelineStartFrame - b.timelineStartFrame);
    let prevEnd: number | null = null;
    for (const clip of clips) {
      if (prevEnd !== null && clip.timelineStartFrame > prevEnd) {
        inverse.unshift({ type: "MoveClip", clipId: clip.id, newTimelineStartFrame: clip.timelineStartFrame });
        clip.timelineStartFrame = prevEnd;
      }
      prevEnd = clip.timelineStartFrame + clip.timelineDurationFrames;
    }
  }
}

function applyAlignClipsToPlayhead(seq: Sequence, cmd: Extract<Command, { type: "AlignClipsToPlayhead" }>, inverse: Command[]): void {
  for (const clipId of cmd.clipIds) {
    const clip = findClip(seq, clipId);
    const track = findTrack(seq, clip.trackId);
    if (track.locked) throw new EditorError("INVALID_TIMELINE", `track ${track.id} is locked — edit refused`);
    if (clip.timelineStartFrame !== cmd.frame) {
      inverse.unshift({ type: "MoveClip", clipId: clip.id, newTimelineStartFrame: clip.timelineStartFrame });
      clip.timelineStartFrame = cmd.frame;
    }
  }
}

export function applyCommand(inputSeq: Sequence, input: unknown): ApplyResult {
  const cmd = parseCommand(input);
  const seq = clone(inputSeq);
  const inverse: Command[] = [];

  switch (cmd.type) {
    case "AddTrack":
      applyAddTrack(seq, cmd, inverse);
      break;
    case "RemoveTrack":
      applyRemoveTrack(seq, cmd, inverse);
      break;
    case "UpdateTrack":
      applyUpdateTrack(seq, cmd, inverse);
      break;
    case "AddClip":
      applyAddClip(seq, cmd, inverse);
      break;
    case "RemoveClip":
      applyRemoveClip(seq, cmd, inverse);
      break;
    case "SplitClip":
      applySplitClip(seq, cmd, inverse);
      break;
    case "TrimClip":
      applyTrimClip(seq, cmd, inverse);
      break;
    case "TrimClipAudioStream":
      applyTrimClipAudioStream(seq, cmd, inverse);
      break;
    case "SetClipAvLink":
      applySetClipAvLink(seq, cmd, inverse);
      break;
    case "AddBus":
      applyAddBus(seq, cmd, inverse);
      break;
    case "RemoveBus":
      applyRemoveBus(seq, cmd, inverse);
      break;
    case "UpdateBus":
      applyUpdateBus(seq, cmd, inverse);
      break;
    case "AssignTrackBus":
      applyAssignTrackBus(seq, cmd, inverse);
      break;
    case "MoveClip":
      applyMoveClip(seq, cmd, inverse);
      break;
    case "RippleDelete":
      applyRippleDelete(seq, cmd, inverse);
      break;
    case "InsertClip":
      applyInsertClip(seq, cmd, inverse);
      break;
    case "ReplaceClip":
      applyReplaceClip(seq, cmd, inverse);
      break;
    case "RelinkAssets":
      applyRelinkAssets(seq, cmd, inverse);
      break;
    case "AddTransition":
      applyAddTransition(seq, cmd, inverse);
      break;
    case "RemoveTransition":
      applyRemoveTransition(seq, cmd, inverse);
      break;
    case "AddEffect":
      applyAddEffect(seq, cmd, inverse);
      break;
    case "RemoveEffect":
      applyRemoveEffect(seq, cmd, inverse);
      break;
    case "AddCaption":
      applyCaptionOrGraphic(seq, cmd.clip, inverse, "CAPTION");
      break;
    case "AddGraphic":
      applyCaptionOrGraphic(seq, cmd.clip, inverse, "GRAPHIC");
      break;
    case "SetKeyframe":
      applySetKeyframe(seq, cmd, inverse);
      break;
    case "RemoveKeyframe":
      applyRemoveKeyframe(seq, cmd, inverse);
      break;
    case "ChangeVolume":
      applyChangeVolume(seq, cmd, inverse);
      break;
    case "ChangePlaybackSpeed":
      applyChangePlaybackSpeed(seq, cmd, inverse);
      break;
    case "UpdateClipProperties":
      applyUpdateClipProperties(seq, cmd, inverse);
      break;
    case "AddMarker":
      applyAddMarker(seq, cmd, inverse);
      break;
    case "RemoveMarker":
      applyRemoveMarker(seq, cmd, inverse);
      break;
    case "UpdateMarker":
      applyUpdateMarker(seq, cmd, inverse);
      break;
    case "GroupClips":
      applyGroupClips(seq, cmd, inverse);
      break;
    case "UngroupClips":
      applyUngroupClips(seq, cmd, inverse);
      break;
    case "CloseGaps":
      applyCloseGaps(seq, cmd, inverse);
      break;
    case "AlignClipsToPlayhead":
      applyAlignClipsToPlayhead(seq, cmd, inverse);
      break;
    case "SetClipGroup":
      applySetClipGroup(seq, cmd, inverse);
      break;
    case "RollEdit":
      applyRollEdit(seq, cmd, inverse);
      break;
    case "SetEffectKeyframe":
      applySetEffectKeyframe(seq, cmd, inverse);
      break;
    case "RemoveEffectKeyframe":
      applyRemoveEffectKeyframe(seq, cmd, inverse);
      break;
    case "SetEffectKeyframes":
      applySetEffectKeyframes(seq, cmd, inverse);
      break;
    case "ToggleEffectParamAnimation":
      applyToggleEffectParamAnimation(seq, cmd, inverse);
      break;
  }

  // Every applied command must leave a structurally valid sequence. This is
  // the gate AI proposals and user edits both pass through — nothing invalid
  // is ever returned or persisted.
  assertValidSequence(seq);
  return { sequence: seq, inverse };
}

export function validateCommand(seq: Sequence, input: unknown): { ok: true; warnings: string[] } | { ok: false; error: string } {
  try {
    const { sequence } = applyCommand(seq, input);
    const report = validateSequence(sequence);
    return { ok: true, warnings: report.warnings };
  } catch (e) {
    return { ok: false, error: e instanceof Error ? e.message : String(e) };
  }
}

export function isValidRangeOnTrack(seq: Sequence, trackId: string, startFrame: number, durationFrames: number): boolean {
  const end = startFrame + durationFrames;
  assertValidRange(startFrame, end, "range check");
  return !seq.clips.some((c) => c.trackId === trackId && c.timelineStartFrame < end && startFrame < clipEndFrame(seq, c));
}
